const localMode=location.protocol==='http:'&&['localhost','127.0.0.1'].includes(location.hostname);
let localService=false,liveTV=null,tvError='',catalogGeneration=0,telemetryBusy=false;
const trafficHistory={down:[],up:[]};
const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function localJSON(path,timeout=18000){if(!localMode)throw Error('Abra a versão conectada pelo serviço local no Mac.');const response=await fetch(path,{cache:'no-store',signal:AbortSignal.timeout(timeout)});let data;try{data=await response.json()}catch{throw Error('O serviço local não respondeu corretamente.')}if(!response.ok)throw Error(data.error||'Consulta indisponível.');return data}
function showServiceStatus(title,detail,ready=false){$('#service-title').textContent=title;$('#service-detail').textContent=detail;$('#service-banner').dataset.state=ready?'ready':'pending'}
async function connectServices(){if(!localMode){showServiceStatus('Modo arquivo · dados limitados','Execute server.py no Mac para conectar TMDB e TV.');$('#catalog-status').textContent='O catálogo usa sua chave configurada no serviço local. Abra a versão conectada no Mac.';loadWeather(true);return}try{await localJSON('/api/health');localService=true;showServiceStatus('Serviço local conectado','Consultando clima, catálogo e Konka…',true);await Promise.allSettled([loadWeather(true),loadCatalog(),refreshTV()]);showServiceStatus('Serviço local conectado',liveTV?'Konka conectada por ADB · dados atualizados':'Clima e catálogo disponíveis; confira o estado da Konka no painel.',true)}catch(e){localService=false;showServiceStatus('Serviço local indisponível','Inicie server.py e recarregue esta página.');$('#catalog-status').textContent=e.message;}}
$('#refresh-services').onclick=connectServices;
loadWeather=async function(force=false){let cached;try{cached=JSON.parse(localStorage.getItem('konka-weather')||'null')}catch{}if(!force&&cached?.current&&cached?.daily&&Number.isFinite(cached.current.temperature_2m)){weather=cached;displayWeather();if(Date.now()-cached.savedAt<1200000)return}try{const data=localMode?await localJSON('/api/weather'):await fetch('https://api.open-meteo.com/v1/forecast?latitude=-19.93&longitude=-44.05&current=temperature_2m,relative_humidity_2m,apparent_temperature,weather_code,wind_speed_10m&daily=weather_code,temperature_2m_max,temperature_2m_min&timezone=America%2FSao_Paulo&forecast_days=3',{signal:AbortSignal.timeout(12000)}).then(r=>{if(!r.ok)throw Error('Clima indisponível');return r.json()});if(!Number.isFinite(data.current?.temperature_2m)||!Array.isArray(data.daily?.time))throw Error('Resposta meteorológica incompleta.');weather={...data,savedAt:Date.now()};weatherError=false;displayWeather();try{localStorage.setItem('konka-weather',JSON.stringify(weather))}catch{}}catch(e){weatherError=true;if(weather)displayWeather();else{$('#weather-condition').textContent='Indisponível · toque para tentar';$('#weather-temp').textContent='—°'}$('#weather-card').title='Não foi possível consultar o clima. Use Atualizar dados.'}};
const providerNames={'8':'Netflix','119':'Prime Video','337':'Disney+','1899':'Max','307':'Globoplay','350':'Apple TV+','531':'Paramount+'};
$('#catalog-type').onchange=loadCatalog;$('#catalog-provider').onchange=loadCatalog;$('#catalog-collection').onchange=loadCatalog;
function gib(bytes){return Number.isFinite(bytes)?(bytes/1073741824).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2}):'—'}
function paintSystem(){if(page!=='home')return;const d=liveTV;$('#system-state').textContent=d?(tvError?'Última leitura · desconectada':'Konka · a cada 15 s'):'Aguardando conexão';$('#ram-total').textContent=gib(d?.ram?.totalBytes||1610612736);const available=d?.ram?.availableBytes,total=d?.ram?.totalBytes;const used=Number.isFinite(available)&&total?total-available:null;$('#ram-used').textContent=gib(used);const percent=used!==null?Math.round(used/total*100):null;$('#ram-percent').textContent=percent===null?'—':percent+'%';$('#ram-arc').style.strokeDashoffset=percent===null?'251.33':String(251.33*(1-percent/100));$('#ram-available').textContent=Number.isFinite(available)?gib(available)+' GiB disponíveis':'Uso total do Android TV';$('#ram-bar').style.width=used!==null?Math.max(0,Math.min(100,used/total*100))+'%':'0%';$('#ram-note').textContent=d?(tvError?'Leitura anterior; abra para reconectar.':'Leitura '+new Date(d.at*1000).toLocaleTimeString('pt-BR')):'Leitura por ADB indisponível';if(d&&!tvError){const n=d.network;$('#home-network-state').textContent='Konka · '+n.transport;$('#home-network-detail').textContent='Leitura ADB · tráfego da TV';$('#network-label').textContent=n.interface?'Konka conectada':'TV · sem rede';$('.network-dot').classList.toggle('offline',!n.interface);$('#network').classList.toggle('offline',!n.interface);$('#network-pill').setAttribute('aria-label',n.interface?'Rede da Konka: '+n.transport:'Konka conectada ao ADB; rede não identificada');$('.signal-reading').innerHTML=(n.rssi??'—')+' <small>dBm</small>';$('.signal-unavailable').textContent=n.rssi!==null?'Sinal medido na Konka':'Sem leitura RSSI';const level=n.rssi===null?0:n.rssi>=-55?4:n.rssi>=-67?3:n.rssi>=-75?2:1;document.querySelectorAll('#network .signal-bars i').forEach((bar,i)=>bar.classList.toggle('measured',i<level));$('.signal-bars').setAttribute('aria-label',n.rssi===null?'Sinal Wi-Fi não disponível':'Força do sinal '+n.rssi+' dBm');if(n.traffic)paintTVTraffic(n.traffic);else{clearTVGraph();$('#home-test-age').textContent='Aguardando 2ª leitura'}}else{$('#home-network-state').textContent=tvError?'Konka desconectada':'Aguardando conexão com a Konka';$('#home-network-detail').textContent='O navegador não mede o Wi-Fi da TV';$('.signal-reading').innerHTML='— <small>dBm</small>';$('.signal-unavailable').textContent='Conecte pelo serviço local';document.querySelectorAll('#network .signal-bars i').forEach(bar=>bar.classList.remove('measured'));$('#network-label').textContent='TV desconectada';$('.network-dot').classList.add('offline');$('#network').classList.add('offline');$('#network-pill').setAttribute('aria-label','TV desconectada: ver rede e conexão');$('#home-test-age').textContent='Sem leitura ao vivo';clearTVGraph()}}
function paintTVTraffic(rates){trafficHistory.down.push(rates.downloadMbps);trafficHistory.up.push(rates.uploadMbps);for(const series of [trafficHistory.down,trafficHistory.up])if(series.length>30)series.shift();const max=Math.max(.01,...trafficHistory.down,...trafficHistory.up);const points=a=>a.map((v,i)=>`${4+i*292/Math.max(1,a.length-1)},${61-v/max*48}`).join(' ');$('#home-down').innerHTML=rates.downloadMbps.toFixed(2)+' <em>Mb/s</em>';$('#home-up').innerHTML=rates.uploadMbps.toFixed(2)+' <em>Mb/s</em>';$('#home-down-line').setAttribute('points',points(trafficHistory.down));$('#home-up-line').setAttribute('points',points(trafficHistory.up));$('#home-chart-empty').textContent='';$('#home-test-age').textContent='Tráfego da TV · ao vivo';$('#home-chart').setAttribute('aria-label','Tráfego medido da interface de rede da Konka. Não é um teste da capacidade da internet.')}
async function refreshTV(){if(telemetryBusy||!localService)return;telemetryBusy=true;try{const data=await localJSON('/api/system');if(!data.connected||!Number.isFinite(data.ram?.totalBytes))throw Error('Leitura incompleta da TV.');liveTV=data;tvError=''}catch(e){tvError=e.message}finally{telemetryBusy=false;paintSystem()}}
function systemPanel(){const d=liveTV,native=typeof PeepTV!=='undefined'&&typeof PeepTV.deviceMetrics==='function',none='Sem leitura ao vivo',missing='Não informado',fresh=d&&Number.isFinite(d.at)&&Date.now()/1000-d.at<45;
 // Somente leituras reais; campos que a fonte não envia aparecem como ausentes, nunca com valores registrados.
 const total=d?.ram?.totalBytes,available=d?.ram?.availableBytes,ramKnown=Number.isFinite(total)&&total>0&&Number.isFinite(available),uptime=d?.uptimeSeconds,app=d?.appMemory?.pssKiB;
 const source=!d?none:(d.source==='Android nativo'?'Android nativo nesta TV':d.source==='ADB · Mac'||!native?'ADB a partir do Mac':String(d.source||missing))+' · '+new Date(d.at*1000).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit'})+(fresh?'':' · leitura antiga');
 const rows=[['Modelo',d?d.model||missing:none],['Android',d?d.android||missing:none],['Plataforma',d?d.platform||missing:none],['Arquitetura',d?d.abi||missing:none],['RAM em uso (sistema)',ramKnown?Math.round((1-available/total)*100)+'% · '+gib(total-available)+' de '+gib(total)+' GiB':d?missing:none],['RAM disponível',ramKnown?gib(available)+' GiB':d?missing:none],['Memória deste app (PSS)',Number.isFinite(app)?(app/1024).toLocaleString('pt-BR',{maximumFractionDigits:1})+' MiB · sem o renderizador WebView':native?missing:'Somente no app da TV'],['Alerta de memória baixa',typeof d?.lowMemory==='boolean'?(d.lowMemory?'Ativo no Android':'Não'):d?missing:none],['Armazenamento livre',Number.isFinite(d?.storage?.availableBytes)?gib(d.storage.availableBytes)+' GiB':d?missing:none],['Resolução',d?d.resolution||missing:none],['Tempo ligado',Number.isFinite(uptime)?(uptime>=86400?Math.floor(uptime/86400)+' d ':'')+Math.floor(uptime%86400/3600)+' h '+Math.floor(uptime%3600/60)+' min':d?missing:none],['Origem e horário',source]];
 const note=tvError||(!d?'Sem leitura da TV. No APK a amostra é local; no navegador, mantenha o serviço do Mac e o ADB conectados.':'RAM em uso é total menos MemAvailable, do sistema inteiro — não é o consumo deste app. MemAvailable já inclui memória recuperável.');
 show('<p class="eyebrow">SUA KONKA POR DENTRO</p><h2>Memória e sistema</h2><p class="inline-note">'+escapeHTML(note)+'</p><dl class="system-table">'+rows.filter(([k,v])=>!(v===missing&&['Plataforma','Arquitetura','Resolução'].includes(k))).map(([k,v])=>'<dt>'+escapeHTML(k)+'</dt><dd>'+escapeHTML(v)+'</dd>').join('')+'</dl><button id="refresh-system" class="panel-button">Atualizar leitura</button><button id="memory-diagnosis" class="text-button">Ver processos que usam RAM</button><div id="memory-processes" class="process-list" role="status"></div>');$('#memory-diagnosis').onclick=loadMemoryDiagnosis;$('#refresh-system').onclick=async()=>{$('#refresh-system').disabled=true;await refreshTV();if($('#refresh-system'))systemPanel()}}
$('#system-card').onclick=systemPanel;
const oldSettingsMenu=settingsMenu;settingsMenu=function(){oldSettingsMenu();$('#menu-tv').onclick=systemPanel};$('#system-settings').onclick=settingsMenu;$('#settings').onclick=settingsMenu;
const oldNetworkPanel=networkPanel;networkPanel=function(){oldNetworkPanel();const info=panel.querySelector('.inline-note');if(info)info.textContent=liveTV&&!tvError?'O card inicial mostra o tráfego real da Konka. O teste abaixo mede a capacidade da internet do Mac/navegador.':'A Konka ainda não está conectada. O teste abaixo mede o Mac/navegador; o sinal da TV exige ADB.';const detail=panel.querySelector('.signal-detail');if(detail&&liveTV&&!tvError){detail.replaceChildren();const p=document.createElement('p');p.textContent=liveTV.network.transport+' · sinal '+(liveTV.network.rssi??'indisponível')+(liveTV.network.rssi!==null?' dBm':'');detail.append(p)}};$('#network').onclick=networkPanel;$('#network-pill').onclick=networkPanel;
const originalUpdateHomeSpeed=updateHomeSpeed;updateHomeSpeed=function(down,up,complete){if(!liveTV||tvError)originalUpdateHomeSpeed(down,up,complete)};
paintSystem();connectServices();

function clearTVGraph(){$('#home-down').innerHTML='— <em>Mb/s</em>';$('#home-up').innerHTML='— <em>Mb/s</em>';$('#home-down-line').setAttribute('points','');$('#home-up-line').setAttribute('points','');$('#home-chart-empty').textContent='Aguardando leitura da TV';trafficHistory.down.length=0;trafficHistory.up.length=0}

async function loadMemoryDiagnosis(){const target=$('#memory-processes'),button=$('#memory-diagnosis');button.disabled=true;target.textContent='Consultando processos da TV…';try{const data=await localJSON('/api/memory');if(!target.isConnected)return;target.innerHTML='<p>Maiores processos por PSS · memória proporcional compartilhada</p>'+data.processes.map(p=>'<div><span>'+escapeHTML(p.name)+'</span><strong>'+(p.pssKiB/1024).toFixed(1)+' MiB</strong></div>').join('')+'<p>Consulta manual. Nenhum aplicativo é encerrado.</p>'}catch(e){if(target.isConnected)target.textContent=e.message}finally{if(button.isConnected)button.disabled=false}}
